import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CWE4YZEv.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md","lastUpdated":1794489637000}'),n={name:"reference/troubleshooting.md"};function s(i,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Find the message you see, then its cause and fix. Run <code>./gradlew svelteDoctor</code> first: it checks the frontend setup and lists most problems on this page at once.</p><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><h3 id="ktor-svelte-found-no-lockfile" tabindex="-1">ktor-svelte found no lockfile <a class="header-anchor" href="#ktor-svelte-found-no-lockfile" aria-label="Permalink to &quot;ktor-svelte found no lockfile&quot;">​</a></h3><p>The frontend has no <code>bun.lock</code>, <code>pnpm-lock.yaml</code>, <code>package-lock.json</code> or <code>yarn.lock</code>, so the plugin cannot tell which package manager to use. Install the dependencies once with your package manager, or set <code>svelte { packageManager = PackageManager.Bun }</code>.</p><h3 id="ktor-svelte-could-not-find-bun-on-path" tabindex="-1">ktor-svelte could not find bun on PATH <a class="header-anchor" href="#ktor-svelte-could-not-find-bun-on-path" aria-label="Permalink to &quot;ktor-svelte could not find bun on PATH&quot;">​</a></h3><p>The package manager the lockfile asks for is not installed, or Gradle cannot see it. Install it, restart the Gradle daemon with <code>./gradlew --stop</code> so it picks up the new <code>PATH</code>, or set <code>packageManager</code> to one you have. To have the plugin download Bun for you, set <code>svelte { bunVersion = &quot;1.3.14&quot; }</code>.</p><h3 id="ktor-svelte-found-no-html-files" tabindex="-1">ktor-svelte found no HTML files <a class="header-anchor" href="#ktor-svelte-found-no-html-files" aria-label="Permalink to &quot;ktor-svelte found no HTML files&quot;">​</a></h3><p>The frontend build produced no pages where the plugin looked. Check that the frontend uses <code>adapter-static</code>, and that <code>svelte { outputDir }</code> matches the adapter&#39;s <code>pages</code> option. The default for both is <code>build</code>.</p><h3 id="ktor-svelte-has-no-setting-x-in-svelte" tabindex="-1">ktor-svelte has no setting &#39;x&#39; in svelte <a class="header-anchor" href="#ktor-svelte-has-no-setting-x-in-svelte" aria-label="Permalink to &quot;ktor-svelte has no setting &#39;x&#39; in svelte { }&quot;">​</a></h3><p>A Groovy build script assigns a setting that does not exist, usually a typo. The message names the closest setting and lists all of them. See <a href="./gradle">Gradle settings</a> for what each one does.</p><h3 id="frontend-libraries-are-out-of-sync" tabindex="-1">Frontend libraries are out of sync <a class="header-anchor" href="#frontend-libraries-are-out-of-sync" aria-label="Permalink to &quot;Frontend libraries are out of sync&quot;">​</a></h3><p><code>build.gradle.kts</code> changed the frontend libraries, but <code>package.json</code>, the lockfile or the generated files were not updated. Run <code>./gradlew svelteSync</code> and commit the result.</p><h3 id="ktor-svelte-generates-vite-config-ts-but-found-your-own-version" tabindex="-1">ktor-svelte generates vite.config.ts, but found your own version <a class="header-anchor" href="#ktor-svelte-generates-vite-config-ts-but-found-your-own-version" aria-label="Permalink to &quot;ktor-svelte generates vite.config.ts, but found your own version&quot;">​</a></h3><p>The plugin needs to own <code>vite.config.ts</code> and the hooks files once frontend libraries are on. Move your own Vite settings to <code>vite.user.ts</code>, merge custom hooks by hand, delete those files and run <code>svelteSync</code>.</p><h3 id="generated-typescript-is-out-of-date" tabindex="-1">Generated TypeScript is out of date <a class="header-anchor" href="#generated-typescript-is-out-of-date" aria-label="Permalink to &quot;Generated TypeScript is out of date&quot;">​</a></h3><p><code>check</code> runs <code>svelteVerifyTs</code>, which found that a route or DTO changed but the committed client did not. Run <code>./gradlew svelteGenerateTs</code>, or start the app in development mode, and commit the files in <code>frontend/src/lib/api</code>.</p><h3 id="undefined-is-not-an-object-evaluating-ts-sys-readfile" tabindex="-1">undefined is not an object (evaluating &#39;ts.sys.readFile&#39;) <a class="header-anchor" href="#undefined-is-not-an-object-evaluating-ts-sys-readfile" aria-label="Permalink to &quot;undefined is not an object (evaluating &#39;ts.sys.readFile&#39;)&quot;">​</a></h3><p>The frontend uses TypeScript 7, which SvelteKit 3 cannot load yet. It usually arrives through an automatic dependency update. Set <code>&quot;typescript&quot;: &quot;^6.0.0&quot;</code> in <code>frontend/package.json</code> and install again. To keep it from coming back, tell your update bot to ignore major versions of <code>typescript</code>.</p><h3 id="the-frontend-build-failed-with-exit-code-1" tabindex="-1">The frontend build failed with exit code 1 <a class="header-anchor" href="#the-frontend-build-failed-with-exit-code-1" aria-label="Permalink to &quot;The frontend build failed with exit code 1&quot;">​</a></h3><p>ktor-svelte hides the package manager and Vite output while it succeeds and prints all of it when it fails, above this message. To see it every time, add <code>-Psvelte.verbose=true</code>.</p><h2 id="startup" tabindex="-1">Startup <a class="header-anchor" href="#startup" aria-label="Permalink to &quot;Startup&quot;">​</a></h2><h3 id="ktor-svelte-found-no-frontend-build" tabindex="-1">ktor-svelte found no frontend build <a class="header-anchor" href="#ktor-svelte-found-no-frontend-build" aria-label="Permalink to &quot;ktor-svelte found no frontend build&quot;">​</a></h3><p>The app runs in production mode, but the JAR has no frontend in it. Build it with the Gradle plugin and without <code>-Psvelte.skip=true</code> or <code>-Psvelte.dev=true</code>. During development, start it with <code>-Dio.ktor.development=true</code>, or use <code>svelteDevAll</code>, which does that for you.</p><h3 id="ktor-svelte-manifest-has-format-version-2-but-this-runtime-reads-version-1" tabindex="-1">ktor-svelte manifest has format version 2, but this runtime reads version 1 <a class="header-anchor" href="#ktor-svelte-manifest-has-format-version-2-but-this-runtime-reads-version-1" aria-label="Permalink to &quot;ktor-svelte manifest has format version 2, but this runtime reads version 1&quot;">​</a></h3><p>The Gradle plugin and <code>ktor-svelte-server</code> have different versions. Use the same version for both. With <code>addRuntimeDependency</code> on, which is the default, the plugin adds the matching runtime for you.</p><h3 id="contentnegotiation-is-already-installed" tabindex="-1">ContentNegotiation is already installed <a class="header-anchor" href="#contentnegotiation-is-already-installed" aria-label="Permalink to &quot;ContentNegotiation is already installed&quot;">​</a></h3><p>You install <code>ContentNegotiation</code> yourself and also list formats in <code>transport { }</code>. Keep one of the two. The same applies to <code>Compression</code> and <code>compression()</code>.</p><h3 id="requestbodylimit-is-already-installed-or-ratelimit-is-already-installed" tabindex="-1">RequestBodyLimit is already installed, or RateLimit is already installed <a class="header-anchor" href="#requestbodylimit-is-already-installed-or-ratelimit-is-already-installed" aria-label="Permalink to &quot;RequestBodyLimit is already installed, or RateLimit is already installed&quot;">​</a></h3><p>ktor-svelte installs these plugins for its body and rate limits. To use your own, set <code>maxApiBodySize = null</code> or <code>rateLimit { enabled = false }</code>.</p><h3 id="ktor-svelte-will-not-proxy-to-this-url-because-it-is-not-on-this-machine" tabindex="-1">ktor-svelte will not proxy to this URL because it is not on this machine <a class="header-anchor" href="#ktor-svelte-will-not-proxy-to-this-url-because-it-is-not-on-this-machine" aria-label="Permalink to &quot;ktor-svelte will not proxy to this URL because it is not on this machine&quot;">​</a></h3><p><code>dev { url }</code> or <code>KTOR_SVELTE_DEV_SERVER</code> points at another host. Use a loopback address, or set <code>dev { allowRemote = true }</code> if you trust that machine.</p><h3 id="install-the-svelte-plugin-before-calling-svelte-in-routing" tabindex="-1">Install the Svelte plugin before calling svelte() in routing <a class="header-anchor" href="#install-the-svelte-plugin-before-calling-svelte-in-routing" aria-label="Permalink to &quot;Install the Svelte plugin before calling svelte() in routing&quot;">​</a></h3><p>With <code>routing = SvelteRouting.Manual</code>, call <code>install(Svelte)</code> before the <code>routing { }</code> block that calls <code>svelte()</code>.</p><h3 id="the-ktor-route-get-about-hides-the-frontend-page-about-html" tabindex="-1">The Ktor route GET /about hides the frontend page about.html <a class="header-anchor" href="#the-ktor-route-get-about-hides-the-frontend-page-about-html" aria-label="Permalink to &quot;The Ktor route GET /about hides the frontend page about.html&quot;">​</a></h3><p>A route in your app answers the same path as a prerendered page, so the page is never served. Move the route under your API prefix, or rename the page.</p><h2 id="requests" tabindex="-1">Requests <a class="header-anchor" href="#requests" aria-label="Permalink to &quot;Requests&quot;">​</a></h2><h3 id="_403-cross-origin-api-request-refused" tabindex="-1">403: Cross-origin API request refused <a class="header-anchor" href="#_403-cross-origin-api-request-refused" aria-label="Permalink to &quot;403: Cross-origin API request refused&quot;">​</a></h3><p>The origin check refused a write from another site. If that site is yours, such as a separate admin frontend, add it with <code>allowedOrigins(&quot;https://admin.example.com&quot;)</code>. Behind a proxy that changes the host, install <code>XForwardedHeaders</code> so the app sees the host the browser used. See <a href="./../security#api-request-guards">Security</a>.</p><h3 id="_413-request-body-is-larger-than-the-limit" tabindex="-1">413: Request body is larger than the limit <a class="header-anchor" href="#_413-request-body-is-larger-than-the-limit" aria-label="Permalink to &quot;413: Request body is larger than the limit&quot;">​</a></h3><p>API bodies are limited to 1 MiB. Raise <code>maxApiBodySize</code> for apps that accept uploads.</p><h3 id="_429-too-many-requests" tabindex="-1">429: Too Many Requests <a class="header-anchor" href="#_429-too-many-requests" aria-label="Permalink to &quot;429: Too Many Requests&quot;">​</a></h3><p>A client sent more than 120 writes to API paths in a minute, or hit a named limit. Behind a proxy, install <code>XForwardedHeaders</code>, or all users share one limit. Raise <code>rateLimit { apiWrites = ... }</code> if your app writes a lot.</p><h3 id="_503-in-development-no-vite-and-no-build" tabindex="-1">503 in development: no Vite and no build <a class="header-anchor" href="#_503-in-development-no-vite-and-no-build" aria-label="Permalink to &quot;503 in development: no Vite and no build&quot;">​</a></h3><p>The app runs in development mode, Vite is not running and there is no frontend build. Start everything with <code>./gradlew svelteDevAll</code>, or Vite alone with <code>./gradlew svelteDev</code>.</p><h3 id="_403-the-dev-proxy-only-answers-requests-from-this-machine" tabindex="-1">403: The dev proxy only answers requests from this machine <a class="header-anchor" href="#_403-the-dev-proxy-only-answers-requests-from-this-machine" aria-label="Permalink to &quot;403: The dev proxy only answers requests from this machine&quot;">​</a></h3><p>You opened the app from another device while it runs in development mode. Set <code>dev { allowRemote = true }</code> on a network you trust.</p><h3 id="a-page-shows-a-blank-screen-after-a-deploy" tabindex="-1">A page shows a blank screen after a deploy <a class="header-anchor" href="#a-page-shows-a-blank-screen-after-a-deploy" aria-label="Permalink to &quot;A page shows a blank screen after a deploy&quot;">​</a></h3><p>The browser has an old page that loads chunks which no longer exist. ktor-svelte answers those with 404 on purpose, so SvelteKit reloads the page. If it does not, check that nothing in front of the app caches HTML: pages are sent with <code>Cache-Control: no-cache</code>.</p><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><h3 id="the-browser-logs-a-websocket-error-for-hmr" tabindex="-1">The browser logs a WebSocket error for HMR <a class="header-anchor" href="#the-browser-logs-a-websocket-error-for-hmr" aria-label="Permalink to &quot;The browser logs a WebSocket error for HMR&quot;">​</a></h3><p>Without <code>server.hmr.clientPort</code> in <code>vite.config.ts</code>, Vite&#39;s client first tries Ktor&#39;s port. Hot reload still works after one error. Projects from <code>svelteInit</code> already set it.</p><h3 id="a-port-is-already-in-use" tabindex="-1">A port is already in use <a class="header-anchor" href="#a-port-is-already-in-use" aria-label="Permalink to &quot;A port is already in use&quot;">​</a></h3><p>A Vite or app process from an earlier run is still alive, usually because a terminal was killed. Run <code>./gradlew --stop</code>, or stop the process on that port. <code>svelteDevAll</code> stops its children even when its terminal closes.</p><h3 id="types-do-not-update-after-a-kotlin-change" tabindex="-1">Types do not update after a Kotlin change <a class="header-anchor" href="#types-do-not-update-after-a-kotlin-change" aria-label="Permalink to &quot;Types do not update after a Kotlin change&quot;">​</a></h3><p>The client is generated when the app starts in development mode with <code>generateTs = true</code>. With <code>svelteDevAll</code>, that happens after every Kotlin change. With separate terminals, restart the app, or run <code>./gradlew svelteGenerateTs</code>.</p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p>Open an <a href="https://github.com/nijasc/ktor-svelte/issues" target="_blank" rel="noreferrer">issue</a> with the full message, your <code>install(Svelte)</code> and <code>svelte { }</code> blocks, and the output of <code>./gradlew svelteDoctor</code>.</p>',58)])])}const f=t(n,[["render",s]]);export{p as __pageData,f as default};
